mapper.select:
SELECT distinct bdn.id, bdn.remarks, bdn.is_deleted, bdn.customer_id, bdn.retreattime, bdn.retreattype, bdn.retreatreason, bdn.auditstatus, bdn.auditperson, bdn.audittime, bd.bed_details, bd.bed_id, cus.customer_name, cus.checkin_date FROM backdown bdn INNER JOIN customer cus ON bdn.customer_id = cus.id INNER JOIN beddetails bd ON bdn.customer_id = bd.customer_id AND bd.is_deleted = 0 INNER JOIN user u ON cus.user_id = u.id
bdn.is_deleted=0
and cus.user_id=#{userId}
and bdn.customer_id=#{customerId}
